/bin/zsh -lc "python3 -B - <<'PY'
from chunks import split_chunks

for length in range(101):
    items = list(range(length))
    for size in range(1, 102):
        result = split_chunks(items, size)
        assert [item for chunk in result for item in chunk] == items
        assert len(result) == (length + size - 1) // size
        assert all(len(chunk) == size for chunk in result[:-1])
        assert not result or 1 <= len(result[-1]) <= size
        assert items == list(range(length))
for items in ([], [1, 2, 3]):
    for size in (0, -1, -10):
        try:
            split_chunks(items, size)
        except ValueError as exc:
            assert str(exc) == 'positive size required'
        else:
            raise AssertionError('Expected ValueError')
print('Passed 10,201 positive-size cases and 6 nonpositive-size cases.')
PY"

